WHERE slug = 'chatgpt' AND lang = 'ru';

-- 7. CLAUDE
UPDATE tools SET
  best_for         = 'Написание текстов, программирование, анализ, длинные документы',
  description      = $d7r$Claude Opus 4.7 предлагает улучшенное программирование и обработку изображений при неизменных ценах. Лимиты запросов удвоены для Pro/Max/Team/Enterprise. Приложение Claude Code переработано с параллельными задачами и поддержкой SSH.$d7r$,
  description_long = $dl7r$Claude — AI-ассистент Anthropic, признанный в 2026 году лидером по качеству следования инструкциям и рассуждениям среди основных AI-ассистентов. Последний релиз, Claude Opus 4.7, улучшает точность программирования и привносит обработку изображений с более высоким разрешением — способность анализировать детализированные изображения, диаграммы и документы с большей точностью — сохраняя цены API неизменными: $5 за миллион токенов на входе и $25 за миллион токенов на выходе.

Значительным улучшением качества жизни в 2026 году стало удвоение лимитов запросов на всех платных тарифах: пользователи Pro, Max, Team и Enterprise теперь могут отправлять вдвое больше сообщений в час, а снижения лимитов в часы пик полностью устранены. Это делает Claude значительно более удобным для профессиональных воркфлоу.

Claude Design, новый продукт от Anthropic Labs, расширяет возможности Claude в сторону визуального вывода — пользователи могут генерировать слайды для презентаций, дизайн-макеты и интерактивные прототипы напрямую через разговор с Claude Opus 4.7. Доступно подписчикам плана Pro и выше без дополнительной платы.

Настольное приложение Claude Code было переработано: параллельное выполнение задач, боковая панель сессий для управления несколькими проектами, встроенная поддержка SSH для удалённой разработки и встроенный терминал. Это делает его одной из наиболее мощных AI-сред разработки, напрямую конкурирующей с Cursor. Claude Platform теперь также доступен на AWS.

Ценообразование: от Free (ограниченные ежедневные сообщения) до Pro за $20/мес, Max за $100/мес и Max за $200/мес. Тарифы Max предлагают значительно более высокую пропускную способность для опытных пользователей и команд разработчиков.

Claude — лучший выбор для тех, кому нужны точные и надёжные ответы на сложные инструкции: техническое написание текстов, анализ документов, ревью кода и рассуждения с длинным контекстом.$dl7r$,
  pros = ARRAY[
    'Claude Opus 4.7 — лучшее следование инструкциям и рассуждения с длинным контекстом',
    'Лимиты запросов удвоены для Pro/Max/Team/Enterprise; снижения в часы пик устранены',
    'Claude Design для Pro+ — генерация слайдов, макетов и прототипов через диалог',
    'Claude Code с параллельными задачами, боковой панелью сессий, SSH и терминалом',
    'Цены API неизменны: $5/$25 за миллион токенов на входе/выходе — предсказуемые расходы'
  ],
  cons = ARRAY[
    'Бесплатный тариф имеет жёсткие дневные лимиты — не подходит для интенсивного использования',
    'Нет нативной генерации изображений (для визуального вывода требуется Claude Design)',
    'Тарифы Max за $100–200/мес дороги по сравнению с ChatGPT Plus за $20/мес',
    'Меньше потребительских функций, чем у ChatGPT — нет встроенного видео, музыки или таблиц',
    'Claude Design всё ещё в предпросмотре Labs — не полностью доступен всем пользователям'
  ]
WHERE slug = 'claude' AND lang = 'ru';

-- 8. GROK
UPDATE tools SET
  best_for         = 'Данные X в реальном времени, клонирование голоса, рассуждения',
  description      = $d8r$Grok 4.3 предлагает контекст 1M токенов, нативный видеовход и встроенные рассуждения за $1,25/M токенов через API. Добавлены Custom Voices API, Speech-to-Text GA и Quality Mode для генерации изображений.$d8r$,
  description_long = $dl8r$Grok — AI-ассистент от xAI, тесно интегрированный с X (бывший Twitter) и доступный как самостоятельный продукт на grok.com. Grok 4.3, текущий релиз, — это существенный апгрейд: поддержка контекстного окна в 1 миллион токенов, нативный видеовход для анализа и встроенные пошаговые рассуждения без необходимости переключаться в отдельный режим.

API стоит $1,25 за миллион токенов на входе, позиционируя Grok 4.3 как конкурентоспособный вариант для разработчиков, которым нужен доступ к данным социальных сетей в реальном времени наряду с мощными общими рассуждениями. Структурированные выходные данные поддерживаются, что упрощает интеграцию в приложения, требующие последовательных JSON или типизированных ответов.

Три новых API расширяют сценарии использования Grok за рамки чата. Custom Voices API позволяет разработчикам клонировать голос из нескольких секунд аудио и использовать его для синтеза речи. Speech-to-Text API, теперь в общей доступности, добавляет временны́е метки на уровне слов и диаризацию говорящих — полезно для транскрипции, заметок о встречах и обработки подкастов. Quality Mode для генерации изображений производит более качественный результат для детализированного визуального контента.

Grok по-прежнему бесплатен на X с дневными ограничениями. SuperGrok, отдельная подписка за $30/мес, открывает более высокие лимиты использования, доступ к API и все продвинутые функции, включая Custom Voices и Quality Mode.

Главное конкурентное преимущество инструмента — интеграция с данными X в реальном времени: Grok может извлекать живые публикации, трендовые темы и свежую информацию, недоступную ни одному другому крупному AI-ассистенту. Это делает его уникально ценным для мониторинга социальных сетей, анализа трендов и исследований в реальном времени. Компромисс — более скромная экосистема интеграций с третьими сторонами по сравнению с ChatGPT или Claude.$dl8r$,
  pros = ARRAY[
    'Grok 4.3 — контекст 1M токенов, нативный видеовход, встроенные рассуждения',
    'Доступ к данным X (Twitter) в реальном времени — уникально среди крупных AI-ассистентов',
    'Custom Voices API: клонирование голоса из нескольких секунд аудио',
    'Speech-to-Text API в GA с временны́ми метками на уровне слов и диаризацией',
    'API за $1,25/M токенов — конкурентная цена с поддержкой структурированного вывода'
  ],
  cons = ARRAY[
    'Тесно привязан к экосистеме X/Twitter — менее полезен без контекста X',
    'SuperGrok за $30/мес предлагает меньше использования, чем Claude Pro или ChatGPT Plus',
    'Меньшая экосистема интеграций с третьими сторонами, чем у ChatGPT или Claude',
    'Качество и последовательность на сложных задачах уступает Claude Opus 4.7',
    'Custom Voices и Quality Mode доступны только в API/SuperGrok — не в бесплатном тарифе'
  ]
WHERE slug = 'grok' AND lang = 'ru';

-- 9. DEEPSEEK
UPDATE tools SET
  best_for         = 'Open-source рассуждения, длинный контекст, дешёвый API',
  description      = $d9r$DeepSeek V4 Preview (24 апреля 2026) предлагает два варианта до 1,6T параметров с контекстом 1M токенов. Hybrid Attention сокращает FLOPs на 73% при 1M токенов. Три режима рассуждений. Open-source.$d9r$,
  description_long = $dl9r$DeepSeek — китайская AI-лаборатория, завоевавшая репутацию за выпуск open-source моделей фронтирного качества по исключительно низкой стоимости. DeepSeek V4 Preview, выпущенный 24 апреля 2026 года, доступен в двух вариантах: V4-Pro с 1,6 триллиона суммарных параметров (49 миллиардов активных) и V4-Flash с 284 миллиардами параметров (13 миллиардов активных). Оба поддерживают контекстное окно в 1 миллион токенов, позволяя анализировать целые кодовые базы, юридические документы или тексты длиной с книгу за одну сессию.

Архитектурная инновация V4 — система Hybrid Attention, объединяющая Compressed Sparse Attention (CSA) и Hierarchical Context Aggregation (HCA). При контексте в 1 миллион токенов V4-Pro использует лишь 27% FLOPs, необходимых DeepSeek V3.2 — резкое улучшение эффективности, делающее задачи с длинным контекстом экономически доступными в масштабе.

Три режима усилия рассуждений — light, standard и deep — позволяют выбирать между скоростью ответа и глубиной рассуждений. Light-режим быстрый и подходит для простых задач; deep-режим задействует расширенную цепочку мыслей для сложных многошаговых проблем. Эта гибкость ценна для разработчиков, создающих приложения со смешанными нагрузками.

Ценообразование агрессивное: V4-Flash стоит $0,14 за миллион токенов на входе и $0,28 за миллион на выходе. V4-Pro — $0,145 за миллион токенов на входе и $3,48 за миллион на выходе. Оба варианта open-source и могут быть развёрнуты локально, что делает DeepSeek наиболее экономичным вариантом для команд, запускающих высокообъёмный инференс или нуждающихся в on-premises деплое.

Веб-интерфейс DeepSeek на chat.deepseek.com бесплатен без необходимости регистрации для базового доступа. Основное ограничение по сравнению с ChatGPT или Claude — экосистема: нет голосового режима, генерации изображений, нативных интеграций с приложениями. DeepSeek — инструмент для разработчиков и исследователей в первую очередь.$dl9r$,
  pros = ARRAY[
    'V4-Pro: 1,6T параметров, 49B активных, контекст 1M токенов — фронтирная производительность по open-source ценам',
    'Hybrid Attention (CSA + HCA) — V4-Pro использует лишь 27% FLOPs vs V3.2 при контексте 1M токенов',
    'Три режима рассуждений (light/standard/deep) — настрой скорость vs глубину для каждого запроса',
    'API V4-Flash за $0,14/$0,28 за миллион токенов — среди дешевейших моделей фронтирного качества',
    'Полностью open-source — возможна локальная установка для конфиденциальности данных'
  ],
  cons = ARRAY[
    'Нет голосового режима, генерации изображений или интеграций с потребительскими приложениями',
    'Веб-интерфейс менее полирован, чем ChatGPT или Claude — продукт для разработчиков',
    'Проблемы конфиденциальности данных для тех, кто не может развернуть локально (китайская компания)',
    'V4-Pro: $3,48/M токенов на выходе — дорого для высокообъёмных задач',
    'Экосистема и поддержка плагинов значительно меньше, чем у OpenAI или Anthropic'
  ]
WHERE slug = 'deepseek' AND lang = 'ru';

-- 10. CURSOR
UPDATE tools SET
  best_for         = 'AI-программирование, multi-repo, облачные агенты, ревью безопасности',
  description      = $d10r$Cursor 3 предлагает единое multi-repo рабочее пространство, облачные агенты, работающие параллельно на ВМ, Canvases для визуального вывода, Automations из Slack или таймеров и постоянный Security Review для Teams.$d10r$,
  description_long = $dl10r$Cursor — AI-первый редактор кода на базе VS Code, разработанный так, чтобы AI-ассистент был основным интерфейсом разработки, а не просто плагином поверх. Cursor 3, текущий мажорный релиз, представляет существенное архитектурное расширение: от редактора для одного файла — к полноценной платформе разработки.

Центральная особенность Cursor 3 — единое multi-repo рабочее пространство: разработчики могут открывать и работать с несколькими репозиториями одновременно, при этом AI-агент сохраняет контекст по всем из них. Облачные агенты работают параллельно на выделенных виртуальных машинах, каждый способен автономно выполнять долгосрочные задачи, записывая свою работу в видео и логи для проверки. Это делает Cursor 3 первым массовым инструментом разработки, где можно делегировать пакет параллельных задач агентам и вернуться к проверенным, залогированным результатам.

Canvases — новый слой визуального вывода: агенты могут создавать сводки ревью PR, архитектурные диаграммы, дашборды тестов и другие структурированные визуальные артефакты прямо внутри рабочего пространства Cursor. Cursor Automations позволяет запускать задачи из Slack-сообщений, запланированных таймеров или конкретных событий в кодовой базе — перемещая Cursor в сторону роли автоматизации, смежной с CI/CD.

Security Review, доступный в тарифах Teams и Enterprise, — это постоянно работающий сканер уязвимостей, выявляющий проблемы безопасности в процессе написания кода, а не на отдельном этапе аудита. Composer 2 — собственная модель команды Cursor, оптимизированная специально для задач редактирования кода.

Ценообразование основано на кредитах: Pro за $20/мес покрывает стандартное использование, Pro+ за $60/мес обеспечивает трёхкратные лимиты для интенсивных пользователей. Бесплатного тарифа нет — Cursor платный с первого дня.

Cursor — лучший выбор для профессиональных разработчиков и инженерных команд, которым нужна глубокая интеграция AI во весь воркфлоу разработки: написание, ревью, тестирование и деплой — а не просто движок подсказок.$dl10r$,
  pros = ARRAY[
    'Единое multi-repo рабочее пространство — AI сохраняет контекст по нескольким репозиториям',
    'Облачные агенты работают параллельно на выделенных ВМ с видео/лог-записью для проверки',
    'Canvases: агенты создают визуальный вывод — ревью PR, дашборды, архитектурные диаграммы',
    'Cursor Automations: запускай агентов из Slack, таймеров или событий кодовой базы',
    'Постоянный Security Review (Teams/Enterprise) — непрерывное сканирование при написании кода'
  ],
  cons = ARRAY[
    'Нет бесплатного тарифа — платный продукт от $20/мес',
    'Pro+ за $60/мес — тройная цена GitHub Copilot для эквивалентного уровня использования',
    'Облачные агенты и Canvases — новые функции, стабильность и надёжность ещё формируются',
    'Cursor Automations и Security Review доступны только в тарифах Teams/Enterprise',
    'Миграция с VS Code требует перенастройки расширений и клавиатурных сочетаний'
  ]
WHERE slug = 'cursor' AND lang = 'ru';
